function OUT = AF7R58ZP_ONEFILE_SENSOR_TO_TARGET_HOTPATH_INSTALL()
% AF7R58ZP
% Exact-SHA-bound production patch after AF7R58ZL.
%
% Purpose:
%   Close the actual sensor -> trigger -> target-modification hot path.
%
% This patch does NOT remove safety/certificate checks. It moves only
% sensor-independent preparation before the 4 ms clock:
%   - current certificate authority verification
%   - current active-reference evaluation
%   - current physical geometry read
%   - future-reference packet preparation
%
% The 4 ms clock then starts immediately before raw_sensor_gate(), i.e. the
% first sensor-dependent operation in REPLANNING_SYSTEM.
%
% Additionally:
%   - write_active_output reuses the already evaluated xd when the active
%     reference version/mode did not change in the same cycle.
%   - observer norm(Ey,2) is replaced by the exact ZYX identity
%       ||Ey||2 = sqrt(1+|sin(theta)|)
%     rounded upward by one representable double.
%
% Only THREE existing methods change:
%   do
%   write_active_output
%   observer_contract_two_events
%
% All other method bodies must remain byte-identical.

PRE_SHA='8ce3089c8a1baddd448d3896f7146d810527efc344f504d2da751d4a5bf53f73';
POST_SHA='afdab70a7a68f545dac3dede9814c95b703cb7823b9da5374ed05004735a1c11';

OUT=struct();
OUT.schema='AF7R58ZP_SENSOR_TO_TARGET_HOTPATH_V1';
OUT.production_modified=false;
OUT.rollback_performed=false;
OUT.status='OPEN';
OUT.error=struct();

pR=which('REPLANNING_SYSTEM');
assert(~isempty(pR)&&isfile(pR),'[AF7R58ZP] REPLANNING_SYSTEM unresolved.');
root=fileparts(pR);
outdir=tempname(root);
[ok,msg]=mkdir(outdir); assert(ok,'%s',msg);
report=fullfile(outdir,'AF7R58ZP_REPORT.txt');
fid=fopen(report,'wt','n','UTF-8'); assert(fid>=0);
cf=onCleanup(@()safe_fclose(fid)); %#ok<NASGU>

say(fid,'====================================================================================================');
say(fid,' AF7R58ZP | SENSOR-TO-TARGET HOT-PATH INSTALL');
say(fid,'====================================================================================================');
say(fid,'[AUTHORITY] exactCurrentSHA=1 | embeddedExactPayload=1 | parseBeforeWrite=1 | rollback=1');
say(fid,'[SAFETY] certificateChecksRemoved=0 | generatorMathChanged=0 | commitMathChanged=0 | cacheMathChanged=0');
say(fid,'[TIMING] hardClockStartsAtFirstSensorDependentOperation=1 | fullReferenceWallTimeStillExternal=1');

backupDir=tempname(root);
backupReady=false;
writesStarted=false;

try
    currentSha=file_hash(pR);
    OUT.pre_sha=currentSha;
    OUT.production_path=pR;

    say(fid,'');
    say(fid,'[A. CURRENT PRODUCTION BINDING]');
    say(fid,' path = %s',pR);
    say(fid,' SHA  = %s',currentSha);
    say(fid,' exact post-ZL authority = %d',strcmp(currentSha,PRE_SHA));
    assert(strcmp(currentSha,PRE_SHA), ...
