    };
    b64=[b64chunks{:}];
    try
        bytes=matlab.net.base64decode(b64);
        bytes=uint8(bytes(:).');
    catch
        jb=java.util.Base64.getDecoder().decode(java.lang.String(b64));
        bytes=typecast(int8(jb),'uint8');
        bytes=bytes(:).';
    end
    patched=native2unicode(bytes,'UTF-8');

    payloadFile=fullfile(outdir,'AF7R58ZP_PAYLOAD_REPLANNING_SYSTEM.m');
    write_utf8(payloadFile,patched);
    payloadSha=file_hash(payloadFile);
    OUT.payload_sha=payloadSha;
    assert(strcmp(payloadSha,POST_SHA),'[AF7R58ZP] embedded payload SHA mismatch.');

    curLines=reshape(regexp(normalize_newlines(current),'\n','split'),1,[]);
    newLines=reshape(regexp(normalize_newlines(patched),'\n','split'),1,[]);
    curDefs=discover_function_headers(curLines);
    newDefs=discover_function_headers(newLines);
    assert(numel(curDefs)==numel(newDefs), ...
        '[AF7R58ZP] function/method count changed.');

    allowed={'do','write_active_output','observer_contract_two_events'};
    changed={};
    unchanged=0;

    % Compare unique method names. Duplicate property get/set methods are
    % handled by exact-header comparison below.
    for k=1:numel(curDefs)
        h=curDefs(k).header;
        hits=find(arrayfun(@(d)strcmp(d.header,h),newDefs));
        if numel(hits)==1
            [A,~,~,~]=function_block_by_exact_header(curLines,curDefs,h);
            [B,~,~,~]=function_block_by_exact_header(newLines,newDefs,h);
            if strcmp(text_hash(strjoin(A,newline)),text_hash(strjoin(B,newline)))
                unchanged=unchanged+1;
            else
                name=method_name_from_header(h);
                changed{end+1}=name; %#ok<AGROW>
                assert(any(strcmp(name,allowed)), ...
                    '[AF7R58ZP] unauthorized changed method: %s',name);
            end
        else
            % Header change is allowed only for write_active_output, whose
            % optional precomputed-xd input preserves all legacy call sites.
            name=method_name_from_header(h);
            assert(strcmp(name,'write_active_output'), ...
                '[AF7R58ZP] unexpected changed function header: %s',h);
            changed{end+1}='write_active_output'; %#ok<AGROW>
        end
    end
    changed=unique(changed,'stable');
    assert(numel(changed)==3 && all(ismember(allowed,changed)), ...
        '[AF7R58ZP] changed-method set is not exactly the intended three.');

    [Do,~,~,~]=method_block_by_name(newLines,newDefs,'do');
    [Wo,~,~,~]=method_block_by_name(newLines,newDefs,'write_active_output');
    [Ob,~,~,~]=method_block_by_name(newLines,newDefs,'observer_contract_two_events');
    doText=strjoin(Do,newline);
    woText=strjoin(Wo,newline);
    obText=strjoin(Ob,newline);

    pGuard=strfind(doText,'obj.assert_runtime_core_certificates_current();');
    pPacket=strfind(doText,'obj.get_active_reference_packet(time,cha,varargin,xd_nom);');
    pHard=strfind(doText,'t_hard_cycle=tic;');
    pSensor=strfind(doText,'obj.raw_sensor_gate(pQ_cur,obj.static_obstacle_map);');

    I=struct();
    I.order_exact = numel(pGuard)==1 && numel(pPacket)==1 && ...
        numel(pHard)==1 && numel(pSensor)==1 && ...
        pGuard<pPacket && pPacket<pHard && pHard<pSensor;
    I.central_certificate_guard_retained = ...
        contains(doText,'obj.assert_runtime_core_certificates_current();');
    I.sensor_gate_retained = ...
        contains(doText,'obj.raw_sensor_gate(pQ_cur,obj.static_obstacle_map);');
    I.trigger_core_retained = ...
        contains(doText,'obj.trigger_core(active,pL_ref,q_ref,time.t);');
    I.generator_call_retained = ...
        contains(doText,'obj.invoke_replan_generator_shadow(');
    I.output_reuse_version_mode_guarded = ...
        contains(doText,'active_version_at_eval=double(obj.active_reference_version);') && ...
        contains(doText,'active_mode_at_eval=char(obj.active_reference_mode);') && ...
        contains(doText,'obj.write_active_output(time.t,xd_nom,xd_active_now);') && ...
        contains(doText,'obj.write_active_output(time.t,xd_nom);');
    I.output_fallback_preserved = ...
        contains(woText,'xd=obj.evaluate_active_reference_xd(t_now,xd_nom);');
    I.observer_svd_removed = ~contains(obText,'norm(Ey,2)');
    I.observer_exact_zyx_norm = ...
        contains(obText,'sqrt(1+abs(sin(double(y1(iq(2))))))') && ...
        contains(obText,'obj.observer_nextfloat_up(');

    vals=struct2cell(I);
    I.all=all(cellfun(@(x)logical(x),vals));
    assert(I.all,'[AF7R58ZP] static semantic invariant failed.');
    OUT.static_invariants=I;

    say(fid,'');
    say(fid,'[B. PATCH SCOPE]');
    say(fid,' changed methods = %s',strjoin(changed,', '));
    say(fid,' all other exact-header blocks unchanged = %d',unchanged);
    fn=fieldnames(I);
    for k=1:numel(fn)
        say(fid,' %-44s = %d',fn{k},logical(I.(fn{k})));
    end

    % Supplementary algebraic regression for exact ZYX spectral norm.
    theta=linspace(-1.55,1.55,101);
    phi=linspace(-pi,pi,17);
    maxAbs=0;
    outward=true;
    for ip=1:numel(phi)
        ph=phi(ip);
        for it=1:numel(theta)
            th=theta(it);
            E=[1,0,-sin(th);0,cos(ph),sin(ph)*cos(th);0,-sin(ph),cos(ph)*cos(th)];
            n0=norm(E,2);
            nf=sqrt(1+abs(sin(th)));
            nu=nextup_positive_or_zero(nf);
            maxAbs=max(maxAbs,abs(n0-nf));
            outward=outward && nu>=n0-8*eps(max(1,n0));
        end
    end
    assert(outward&&maxAbs<1e-12,'[AF7R58ZP] ZYX norm regression failed.');
    OUT.zyx_norm_max_abs=maxAbs;

    say(fid,'');
    say(fid,'[C. ZYX NORM SUPPLEMENTARY REGRESSION]');
    say(fid,' max |SVD-formula| = %.17g',maxAbs);
    say(fid,' upward hard-support closure = %d',outward);

    % Full class parse before any production write.
    parseDir=fullfile(outdir,'AF7R58ZP_PREFLIGHT');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZP_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(patched,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    write_utf8(fullfile(parseDir,[parseName '.m']),parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZP] patched class parse failed.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[D. PREFLIGHT BEFORE WRITE]');
    say(fid,' current source exact    = 1');
    say(fid,' payload SHA exact       = 1');
    say(fid,' unauthorized changes    = 0');
    say(fid,' full MATLAB class parse = 1');
    say(fid,' production writes       = 0');

    [ok,msg]=mkdir(backupDir); assert(ok,'%s',msg);
    backupReady=true;
    OUT.backup_directory=backupDir;
    copyfile(pR,fullfile(backupDir,'REPLANNING_SYSTEM.m'));

    writesStarted=true;
    write_utf8(pR,patched);
    rehash;
    postSha=file_hash(pR);
    assert(strcmp(postSha,POST_SHA),'[AF7R58ZP] post-write SHA mismatch.');

    OUT.post_sha=postSha;
    OUT.production_modified=true;
    OUT.status='SENSOR_TO_TARGET_HOTPATH_INSTALLED__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[E. INSTALL RESULT]');
    say(fid,' production modified                     = 1');
    say(fid,' rollback performed                      = 0');
    say(fid,' hard clock begins at raw_sensor_gate    = 1');
    say(fid,' certificate verification retained       = 1');
    say(fid,' future reference packet precomputed     = 1');
    say(fid,' same-authority output re-evaluation cut = 1');
    say(fid,' same-cycle commit output semantics kept = 1');
    say(fid,' observer SVD replaced exactly           = 1');
    say(fid,' generator / commit / cache math changed = 0');
    say(fid,' post SHA                                = %s',postSha);

catch ME
    if backupReady && writesStarted
        try
            copyfile(fullfile(backupDir,'REPLANNING_SYSTEM.m'),pR,'f');
            rehash;
            OUT.rollback_performed=true;
        catch
        end
    end
    OUT.production_modified=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_COMPLETE';
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});

    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier          = %s',ME.identifier);
    say(fid,' message             = %s',ME.message);
    say(fid,' rollback performed  = %d',OUT.rollback_performed);
    say(fid,' production modified = 0');
end

save(fullfile(outdir,'AF7R58ZP_OUT.mat'),'OUT','-v7');
assignin('base','AF7R58ZP_OUT',OUT);
say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',fullfile(outdir,'AF7R58ZP_OUT.mat'));
say(fid,'status = %s',OUT.status);
end


function defs=discover_function_headers(lines)
lines=reshape(lines,1,[]);
defs=struct('line',{},'indent',{},'header',{},'header_end',{});
defs=defs([]);
for k=1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ')
        [hdr,ke]=collect_function_header(lines,k);
        defs(end+1)=struct('line',k,'indent',leading_ws_count(lines{k}), ...
            'header',hdr,'header_end',ke); %#ok<AGROW>
    end
end
end


function [b,i0,i1,hdr]=function_block_by_exact_header(lines,defs,header)
hits=find(arrayfun(@(d)strcmp(d.header,header),defs));
assert(numel(hits)==1,'[AF7R58ZP] exact header count=%d.',numel(hits));
d=defs(hits);
i0=d.line; hdr=d.header; i1=numel(lines);
for k=i0+1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ') && ...
            leading_ws_count(lines{k})==d.indent
        i1=k-1; break;
    end
end
b=reshape(lines(i0:i1),1,[]);
end


function [b,i0,i1,hdr]=method_block_by_name(lines,defs,name)
hits=[];
for k=1:numel(defs)
    if strcmp(method_name_from_header(defs(k).header),name)
        hits(end+1)=k; %#ok<AGROW>
    end
end
assert(numel(hits)==1,'[AF7R58ZP] method %s count=%d.',name,numel(hits));
d=defs(hits);
i0=d.line; hdr=d.header; i1=numel(lines);
for k=i0+1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ') && ...
            leading_ws_count(lines{k})==d.indent
        i1=k-1; break;
    end
end
b=reshape(lines(i0:i1),1,[]);
end


function name=method_name_from_header(header)
q=strfind(header,'(');
assert(~isempty(q));
left=strtrim(header(1:q(1)-1));
tok=regexp(left,'([A-Za-z_]\w*)\s*$','tokens','once');
assert(~isempty(tok));
name=tok{1};
end


function [hdr,kend]=collect_function_header(lines,k0)
parts={strtrim(lines{k0})};
kend=k0;
while endsWith(strtrim(parts{end}),'...')
    parts{end}=strtrim(parts{end}(1:end-3));
    kend=kend+1;
    assert(kend<=numel(lines));
    parts{end+1}=strtrim(lines{kend}); %#ok<AGROW>
end
hdr=strjoin(parts,' ');
end


function n=leading_ws_count(line)
n=0;
for k=1:numel(line)
    if isspace(line(k)),n=n+1;else,break;end
end
end


function y=nextup_positive_or_zero(x)
x=double(x);
assert(isfinite(x)&&x>=0);
if x==0
    y=realmin*eps(1);
    return;
end
u=typecast(x,'uint64');
y=typecast(u+uint64(1),'double');
end


function s=normalize_newlines(s)
s=strrep(s,sprintf('\r\n'),sprintf('\n'));
s=strrep(s,sprintf('\r'),sprintf('\n'));
end


function s=read_utf8(p)
fid=fopen(p,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');
s=native2unicode(b.','UTF-8');
end


function write_utf8(p,s)
fid=fopen(p,'wb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=unicode2native(s,'UTF-8');
n=fwrite(fid,b,'uint8');
assert(n==numel(b));
end


function h=file_hash(p)
fid=fopen(p,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');
m=java.security.MessageDigest.getInstance('SHA-256');
m.update(b);
d=typecast(m.digest(),'uint8');
h=lower(reshape(dec2hex(d,2).',1,[]));
end


function h=text_hash(s)
b=unicode2native(s,'UTF-8');
m=java.security.MessageDigest.getInstance('SHA-256');
m.update(uint8(b));
d=typecast(m.digest(),'uint8');
h=lower(reshape(dec2hex(d,2).',1,[]));
end


function safe_rmpath(p)
try
    q=strsplit(path,pathsep);
    if any(strcmpi(q,p)),rmpath(p);end
catch
end
end


function safe_fclose(fid)
try
    if fid>=0,fclose(fid);end
catch
end
end


function say(fid,fmt,varargin)
ss=sprintf(fmt,varargin{:});
fprintf(1,'%s\n',ss);
fprintf(fid,'%s\n',ss);
end
